        repXform.property("ADBE Vector Repeater Position").setValue([0, 0]);
        repXform.property("ADBE Vector Repeater Rotation").setValue(30.0);

        return "SUCCESS: Created shape repeater with 12 radial copies.";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

