            if (eff.property("Wipe Angle")) eff.property("Wipe Angle").setValue(90);
            if (eff.property("Feather")) eff.property("Feather").setValue(35);
        }
        return "SUCCESS: Applied Linear Wipe to " + selected.length + " layer(s).";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
