    try {
        var proj = app.project || app.newProject();
        var comp = proj.items.addComp("Main Comp 57", 3840, 2160, 1.0, 5, 24);
        comp.openInViewer();
        var bg = comp.layers.addSolid([0.05, 0.05, 0.08], "Background", 3840, 2160, 1.0, 5);
        var textLayer = comp.layers.addText("CYBERPUNK 2077");
        var textProp = textLayer.property("Source Text");
        var textDoc = textProp.value;
        textDoc.fontSize = 72;
        textDoc.justification = ParagraphJustification.CENTER_JUSTIFY;
        textDoc.fillColor = [1, 1, 1];
        textProp.setValue(textDoc);
        textLayer.property("Position").setValue([3840/2, 2160/2]);
        return "SUCCESS: Title scene 'Main Comp 57' created.";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

