(function() {
    app.beginUndoGroup("Apply Gaussian Blur");
    try {
        var comp = app.project.activeItem;
        if (!(comp instanceof CompItem)) return "ERROR: Please open a composition.";
        var selected = comp.selectedLayers;
        if (selected.length === 0) return "ERROR: Select at least one layer.";
        for (var i = 0; i < selected.length; i++) {
            var layer = selected[i];
            var effects = layer.property("ADBE Effect Parade");
            var effect = effects.addProperty("ADBE Gaussian Blur 2");
            if (effect && effect.property("Blurriness")) {
                effect.property("Blurriness").setValue(80);
            }
        }
        return "SUCCESS: Added Gaussian Blur to " + selected.length + " layer(s).";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

