        animator.name = "Typewriter";

        var selector = animator.property("ADBE Text Selectors").addProperty("ADBE Text Selector");
        var opacity = animator.property("ADBE Text Animator Properties").addProperty("ADBE Text Opacity");
        opacity.setValue(0);

