        var t0 = textLayer.inPoint;
        endProp.setValueAtTime(t0, 0);
        endProp.setValueAtTime(t0 + 1.5, 100);

        return "SUCCESS: Typewriter animation created for 'GENERATIVE AI ASSISTANT'.";
    } catch (e) {
        return "ERROR: " + e.toString();
