            var myShape = new Shape();
            myShape.vertices = [[-comp.width/2, -300], [comp.width/2, -300], [comp.width/2, 300], [-comp.width/2, 300]];
            myShape.closed = true;
            mask.property("ADBE Mask Shape").setValue(myShape);
            mask.property("ADBE Mask Feather").setValue([40, 40]);
        }
        return "SUCCESS: Created wide cinematic letterbox mask mask with 40px feather.";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

