(function() {
    app.beginUndoGroup("Typewriter Text Animation");
    try {
        var comp = app.project.activeItem;
        if (!(comp instanceof CompItem)) return "ERROR: Open a composition.";
        var textLayer = comp.layers.addText("GENERATIVE AI ASSISTANT");
