            var eff = effects.addProperty("ADBE Ramp");
            if (eff.property("Start Color")) eff.property("Start Color").setValue([0.1, 0.15, 0.3]);
            if (eff.property("End Color")) eff.property("End Color").setValue([0.02, 0.02, 0.05]);
            if (eff.property("Ramp Shape")) eff.property("Ramp Shape").setValue(2); // Radial Ramp
        }
        return "SUCCESS: Applied Gradient Ramp to " + selected.length + " layer(s).";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

