(function() {
    app.beginUndoGroup("Create Mask (square vignette mask)");
    try {
        var comp = app.project.activeItem;
        if (!(comp instanceof CompItem)) return "ERROR: Open a composition.";
        var selected = comp.selectedLayers;
        if (selected.length === 0) return "ERROR: Select at least one layer.";
        for (var i = 0; i < selected.length; i++) {
            var layer = selected[i];
            var masks = layer.property("ADBE Mask Parade");
            var mask = masks.addProperty("ADBE Mask Atom");
            mask.maskMode = MaskMode.ADD;

            var myShape = new Shape();
            myShape.vertices = [[-300, -300], [300, -300], [300, 300], [-300, 300]];
            myShape.closed = true;
            mask.property("ADBE Mask Shape").setValue(myShape);
            mask.property("ADBE Mask Feather").setValue([60, 60]);
        }
        return "SUCCESS: Created square vignette mask mask with 60px feather.";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

