        endProp.setValueAtTime(t0, 0);
        endProp.setValueAtTime(t0 + 3.5, 100);

        return "SUCCESS: Typewriter animation created for 'AFTER EFFECTS EXTENSION'.";
    } catch (e) {
        return "ERROR: " + e.toString();
    } finally {
        app.endUndoGroup();
    }
})();

